class ConfigEditor extends LitElement {

static get properties() {
	return {
		_hass: {type: Object},
		code: {type: String},
		fileList: {type: Array},
		openedFile: {type: String},
		infoLine: {type: String},
		alertLine: {type: String},
		edit: {}
	};
}

constructor() {
	super();
	this.code = '';
	this.fileList = [];
	this.openedFile = '';
	this.infoLine = '';
	this.alertLine = '';
	this.cmobj = null;
}

static get styles() {
	return css`
	
	textarea{
		width:98%;
		height:84vh;
		padding:5px;
		overflow-wrap:normal;
		white-space:pre}
	.top{
		min-height:calc(95vh - var(--header-height,56px))}
	.pin,.filebar{
		display:flex}
	.pin label{
		cursor:pointer}
	.right{text-align:right;
		flex-grow:1}
	.right button{
		font-family:Times,serif;
		font-weight:bold}
	.pin,.bar{
		position:-webkit-sticky;
		position:sticky;
		z-index:2;}
	.pin{
		top:0;
		background:var(--secondary-background-color,silver)}
	.bar{
		bottom:0;
		z-index:2;
		background:var(--app-header-background-color,gray);
		color:var(--app-header-text-color,white);
		white-space:nowrap;
		overflow:hidden;
		text-overflow:ellipsis}
	.bar i{
		background:#ff7a81;
		cursor:pointer}
	.bar select{
		flex-grow:1;
		text-overflow:ellipsis;
		width:100%;
		overflow:hidden}
		
	.wrapper {
		position: relative;height: 100%;
		border: 1px solid var(--divider-color, #e0e0e0);}
		

	#theme::before{content:'\\25EA';}
	#theme.light::before{content:'\\2600\\FE0E';}
	#theme.dark::before{content:'\\1F319\\FE0E';}


		
	.cm-editor {
		z-index: 0;
		height: calc(92vh - var(--header-height,56px));
		min-height: 80vh;
		font-family: monospace;}

	.cm-scroller {
		font-family: monospace;}

	.cm-tooltip-autocomplete {
		z-index: 10;}


`;
}

colorMode(){
	const btn = this.renderRoot.querySelector('#theme');
	let c="auto";
	if (btn.classList.contains('auto')) {c = "dark";}
	if (btn.classList.contains('dark')) {c = "light";}
	btn.className = c;
	this.localSet("theme",c);
	this.edit.theme = c;
	this.setTheme();
}

render(){
	
	const targetver=5;
	
	if(!this._hass){return html``;}


	
	if(this.fileList.length<1){
		this.openedFile = this.localGet('Open')||'';
		this.edit.ext = this.localGet('Ext')||'yaml';
		this.edit.editor = this.localGet('Editor')||'CodeM';
		if(this.fileList = JSON.parse(this.localGet('List'+this.edit.ext))){
			if(this.extOk(this.openedFile)){
				setTimeout(this.oldText, 500, this);
			}
		}else{this.List();}
	}
	const hver=this.edit.cver;
	const dlink=html`<a href="https://github.com/junkfix/config-editor">download</a>`;

	return html`
	<ha-card>
		${(!this._hass.config.components.includes("config_editor")) ? html`<div>Missing 'config_editor:' in configuration.yaml ${dlink}</div>` : ''}
		${(hver && hver != targetver) ? html`<div>Please ${dlink} upgrade from ${hver} to ${targetver}</div>` : ''}
		<div class="top">
		<div class="pin">
			<div class="left"><button @click="${this.reLoad}">Reload</button></div>
			<div class="right">
			${(this.edit.editor == 'CodeM' ) ? html`<button @click="${this.colorMode}" id="theme" class=${this.edit.theme}></button>` : html``}
			<button @click="${e=>this.txtSize(0)}">-</button>
			<button @click="${e=>this.txtSize(2)}">A</button>
			<button @click="${e=>this.txtSize(1)}">+</button>
			<select @change=${this.extChange}>
			${["yaml","py","json","conf","js","txt","log","jinja","all"].map(value =>
			html`<option ?selected=${value === this.edit.ext }
				value=${value}>${value.toUpperCase()}</option>`)}
			</select>
			<select title="Editor" @change=${this.newEdit}>
			${["CodeM","BuiltIn","Plain"].map(value =>
			html`<option ?selected=${value === this.edit.editor }
				value=${value}>${value}</option>`)}
			</select>
			</div>
		</div>
		${(this.edit.editor != 'BuiltIn' ) ?
		html`<div class="wrapper" @keydown=${this.saveKey}><textarea rows="10" ?readonly=${!0==this.edit.readonly}
			@change=${this.updateText} id="code">${this.code}</textarea></div>`:
		html`<ha-code-editor id="code" mode="yaml" ?readOnly=${!0==this.edit.readonly}
			@keydown=${this.saveKey} .hass=${this._hass} @value-changed=${this.updateText}
			dir="ltr" autocomplete-entities autocomplete-icons></ha-code-editor>`}
		</div>
		${this.edit.hidefooter ? '' : html`
		<div class="bar">
			<div>${this.alertLine}</div>
			<div class="filebar">${!this.edit.readonly ?
			html`<button @click="${this.Save}">Save</button>`:''}
			<select @change=${this.Load}>
			${[''].concat(this.fileList).map(value =>
			html`<option ?selected=${value === this.openedFile}
				value=${value}>${value}</option>`)}
			</select>
			<button @click="${this.List}">Get List</button>
			</div>
			<code>#${this.infoLine}</code>
		</div>`}
	</ha-card>
`;

}

txtSize(e){
	if(e<3){
		if(e>1){
			this.edit.size=100;
		}else if(e>0){
			this.edit.size+=5;
		}else{
			this.edit.size-=5;
		}
		this.localSet('Size', this.edit.size);
		this.infoLine = 'size: '+this.edit.size;
	}
	this.renderRoot.querySelector('#code').style.fontSize=this.edit.size+'%';
	if(this.cmobj && this.sizeConf){
		this.cmobj.dispatch({
			effects: this.sizeConf.reconfigure(this.getSizeTheme())
		});
	}
}

extChange(e){
	this.edit.ext = e.target.value;
	this.localSet('Ext', this.edit.ext);
	if(this.cmobj){
		this.setLang(this.edit.ext);
	}else{
		this.openedFile = '';
		this.oldText(this);
	}
	this.List(this.openedFile);
}

newEdit(e){
	this.edit.editor = e.target.value;
	this.localSet('Editor', this.edit.editor);
	this.reLoad();
}

updateText(e) {
	e.stopPropagation();
	switch(this.edit.editor){
		case 'BuiltIn': this.code = e.detail.value; break;
		case 'CodeM': this.code = this.cmobj.state.doc.toString(); break;
		default: this.code = e.target.value;
	}
	if(this.openedFile){this.localSet('Text', this.code);}
}

Unsave(){
	this.code = this.localGet('Unsaved');
	this.renderRoot.querySelector('#code').value=this.code;
	if(this.cmobj){this.setCmText(this.code);}
	this.localSet('Unsaved','');
	this.alertLine = '';
	this.Toast("Loaded from browser",1500);
}

localGet(e){
	return localStorage.getItem('config_editor'+e);
}

localSet(k,v){
	localStorage.setItem('config_editor'+k,v);
}

cmd(action, data, file){
	return this._hass.callWS({type: "config_editor/ws", action: action,
	data: data, file: file, ext: this.edit.ext, depth: this.edit.depth});
}

saveList(){
	this.localSet('List'+this.edit.ext, JSON.stringify(this.fileList));
}

reLoad(e){
	this.Load({target:{value:this.openedFile},reload:1});
}
oldText(dhis){
	dhis.Load({target:{value:dhis.openedFile}});
}

saveKey(e) {
	if((e.key == 'S' || e.key == 's' ) && (e.ctrlKey || e.metaKey)){
		e.preventDefault();
		this.Save();
		return false;
	}
	e.stopPropagation();
	return true;
}

Toast(message, duration){
	const e = new Event("hass-notification",
		{bubbles: true, cancelable: false, composed: true});
	e.detail = {message, duration, dismissable: true,
		//action: {text:"Save",action:()=>{this.sureSave();}},
	};
	document.querySelector("home-assistant").dispatchEvent(e);
}
//sureSave(){console.log(this.openedFile);}

async Coder(){
	const c="ha-yaml-editor";
	if(!customElements.get(c)){
		await customElements.whenDefined("partial-panel-resolver");
		const p = document.createElement('partial-panel-resolver');
		p.hass = {panels: [{url_path: "tmp", component_name: "config"}]};
		p._updateRoutes();
		await p.routerOptions.routes.tmp.load();
		const d=document.createElement("ha-panel-config");
		await d.routerOptions.routes.automation.load();
	}
	const a=document.createElement(c);
	if(!a){
		this.localSet('Editor', 'Plain');
		console.error('failed '+c);
	}

	this.render();
}

autoComp(context) {
	const word = context.matchBefore(/[\w.]+/);
	
	if (!word || word.text.length <= 2) {return null;}
	
	const search = word.text.toLowerCase();
	const entities = Object.keys(this._hass?.states || {});
	
	const options = entities.filter(id => id.toLowerCase().includes(search)).slice(0, 200).map(id => ({label: id,type: 'variable'}));
	
	if (!options.length) {return null;}
	
	return {from: word.from, options};
}




setCmText(text) {
	if (!this.cmobj) return;
	
	this.cmobj.dispatch({
	changes: {
		from: 0,
		to: this.cmobj.state.doc.length,
		insert: text ?? ''
	}
	});
}

getCmExt(ext) {

	const extmode = {
		yaml: () => window.CM.yaml(),
		yml: () => window.CM.yaml(),
		jinja: () => window.CM.yaml(),
		py: () => window.CM.python(),
		json: () => window.CM.javascript(),
		js: () => window.CM.javascript(),
		conf: () => window.CM.properties(),
		ini: () => window.CM.properties(),
		sh: () => window.CM.shell(),
		bash: () => window.CM.shell()
	};
	
	const op = this.openedFile?.split('.').pop();
	ext = ext ? ext : (this.edit.ext === 'all' ? op : this.edit.ext);
	return (extmode[ext] || (() => []))();
}

setLang(ext) {
	if (!this.cmobj || !this.languageConf) return;
	
	this.cmobj.dispatch({effects: this.languageConf.reconfigure(this.getCmExt(ext))});
}

getTheme(){
	let theme = window.CM.lightTheme;
	const isDark = this.edit.theme === "auto" && this._hass?.themes?.darkMode;
	const setDark = this.edit.theme === "dark";
	if (isDark || setDark) {theme = window.CM.darkTheme;}
	return theme;
}

setTheme() {
	this.cmobj.dispatch({effects: this.themeConf.reconfigure(this.getTheme())});
}


getSizeTheme(){
	return window.CM.EditorView.theme({'&': {fontSize: this.edit.size + '%'}});
}

getReadonly(){
	const readonly = this.edit.readonly === true;
	return [
		window.CM.EditorState.readOnly.of(readonly),
		window.CM.EditorView.editable.of(!readonly)
	];
}

updated(changedProperties) {
	super.updated(changedProperties);

	const textarea = this.shadowRoot.querySelector('#code');

	if (this.edit.editor === 'CodeM') {
		if (textarea && !this.cmobj && window.CM) {
			this.languageConf = new window.CM.Compartment();
			this.themeConf = new window.CM.Compartment();
			this.readOnlyConf = new window.CM.Compartment();
			this.sizeConf = new window.CM.Compartment();

			this.cmobj = new window.CM.EditorView({
				doc: textarea.value || this.code || '',
				parent: textarea.parentElement,
				extensions: [
					window.CM.basicSetup,
					window.CM.search(),

					this.languageConf.of(this.getCmExt()),

					this.themeConf.of(this.getTheme()),
					this.sizeConf.of(this.getSizeTheme()),

					this.readOnlyConf.of(this.getReadonly()),

					window.CM.autocompletion({
						activateOnTyping: true,
						override: [(context) => this.autoComp(context)]
					}),

					window.CM.EditorView.updateListener.of((update) => {
						if (!update.docChanged) return;

						this.code = update.state.doc.toString();
						textarea.value = this.code;

						if (this.openedFile) {
							this.localSet('Text', this.code);
						}
					})
				]
			});

			textarea.style.display = 'none';
			this.txtSize(3);
		} else if (this.cmobj) {
			this.setTheme();
			if (this.readOnlyConf){
				this.cmobj.dispatch({
				effects: this.readOnlyConf.reconfigure(this.getReadonly())
				});
			}
		}
	} else {
		if (this.cmobj) {
			this.cmobj.destroy();
			this.cmobj = null;
			this.languageConf = null;
			this.themeConf = null;
			this.readOnlyConf = null;
			this.sizeConf = null;
			if (textarea) {
				textarea.style.display = '';
			}
		}
	}
}




async List(old){
	this.infoLine = 'List Loading...';
	const e=await this.cmd('list','','');
	if(e){
		this.edit.cver = e.cver;
		this.infoLine = e.msg;
		this.fileList = e.file.slice().sort();
		this.saveList();
		if(this.cmobj && old){
			this.fileList.unshift(this.openedFile);
		}else{
			if(this.extOk(this.openedFile)){
				setTimeout(this.oldText, 500, this);
			}
		}
	}
}

async Load(x) {
	if(x.target.value == this.openedFile && this.code && !x.hasOwnProperty('reload')){return;}
	if(this.edit.orgCode.trim() != this.code.trim()){
		if(!confirm("Switch without Saving?")){x.target.value = this.openedFile; return;}
	}
	this.code = ''; this.renderRoot.querySelector('#code').value='';this.infoLine = '';
	this.openedFile = x.target.value;
	if(this.openedFile){
		this.infoLine = 'Loading: '+this.openedFile;
		const e=await this.cmd('load','',this.openedFile);
		if(e){
			this.edit.cver = e.cver;
			this.openedFile = e.file;
			this.infoLine = e.msg;
			this.Toast(this.infoLine,1000);
			const uns={f:this.localGet('Open'), d:this.localGet('Text')};
			if(uns.f == this.openedFile && uns.d && uns.d != e.data){
				this.localSet('Unsaved', uns.d);
				this.alertLine = html`<i @click="${this.Unsave}"> 
				Load unsaved from browser </i>`;
			}else{
				this.localSet('Text','');this.alertLine = '';
			}
			this.renderRoot.querySelector('#code').value=e.data;
			this.code = e.data;
			
			if(this.cmobj){
				this.setCmText(e.data);
				this.setLang();
			}
			
		}
	}
	this.edit.orgCode = this.code;
	this.localSet('Open', this.openedFile);
	this.txtSize(3);
}

extOk(f){
	if(f.length && (this.edit.ext=='all' || f.endsWith("."+this.edit.ext) )){return 1;}
	return 0;
}

async Save() {
	const val = this.edit.editor === 'CodeM'
		? this.cmobj.state.doc.toString()
		: this.renderRoot.querySelector('#code').value;

	if (val !== this.code || this.edit.readonly) {
		this.infoLine = 'Something not right!';
		return;
	}

	let savenew = 0;
	if(!this.openedFile && this.code){
		this.openedFile=prompt("type abc."+this.edit.ext+" or folder/abc."+this.edit.ext);
		savenew=1;
	}
	if(this.extOk(this.openedFile)){
		if(!confirm("Save?")){if(savenew){this.openedFile='';}return;}
		if(!this.code){this.infoLine=''; this.infoLine = 'Text is empty!'; return;}
		this.infoLine = 'Saving: '+this.openedFile;
		const e=await this.cmd('save', this.code, this.openedFile);
		if(e){
			this.infoLine = e.msg;
			this.Toast(this.infoLine,2000);
			if(e.msg.includes('Saved:')){
				this.localSet('Text','');
				if(savenew){
					this.fileList.unshift(this.openedFile);
					this.saveList();
				}
			}
		}
	}else{this.openedFile='';}
	this.edit.orgCode = this.code;
}

getCardSize() {
	return 5;
}

setConfig(config) {
	this.edit = {file: '', hidefooter: false, readonly: false, theme: '', editor: false, size: 0, depth: 2, ext: '', orgCode: '', coder: 1, cver: 0, ...config};
	if(this.edit.file){
		const f=this.edit.file.split('.')[1];
		if(f){
			this.localSet('Open', this.edit.file);
			this.localSet('Ext', f);
		}
	}
	if(!this.edit.size){
		this.edit.size=Number(this.localGet('Size'))||100;
	}
	if(!this.edit.theme){
		this.edit.theme = this.localGet("theme") || 'auto';
	}
	this.Coder();
}

set hass(hass) {
	this._hass = hass;
}

shouldUpdate(changedProps) {
	for(const e of ['code','openedFile','fileList','infoLine','alertLine','edit']) {
		if(changedProps.has(e)){return true;}
	}
}

} customElements.define('config-editor-card', ConfigEditor);

window.customCards = window.customCards || [];
window.customCards.push({
	type: 'config-editor-card',
	name: 'Config Editor Card',
	preview: false,
	description: 'Basic editor for configuration.yaml'
});
